using System.Reflection;

namespace Aion.GameServer.Model;

/// <summary>
/// Dialog-action ids exchanged with the client.
/// Java parity: model/DialogAction.
/// </summary>
/// <remarks>
/// Java converted this from an enum to a class of int constants (JVM enums are limited to ~3000
/// values by the 64KB bytecode limit). Ported 1:1 as int constants; the int-&gt;name lookup is built
