    private static readonly Dictionary<int, string> NameById = BuildNameById();

    // Java parity: static initializer building nameById via reflection over the public int constants.
    private static Dictionary<int, string> BuildNameById()
    {
        var nameById = new Dictionary<int, string>();
        foreach (FieldInfo publicField in typeof(DialogAction).GetFields(BindingFlags.Public | BindingFlags.Static))
        {
            if (publicField.IsLiteral && !publicField.IsInitOnly && publicField.FieldType == typeof(int))
            {
                int dialogActionId = (int)publicField.GetRawConstantValue()!;
                if (nameById.TryGetValue(dialogActionId, out string? previousName))
                    throw new InvalidOperationException("Duplicate id " + dialogActionId + ": " + publicField.Name + ", " + previousName);
                nameById[dialogActionId] = publicField.Name;
            }
        }
        return nameById;
    }

    // Java parity: nameOf(int)
    public static string? NameOf(int dialogActionId) => NameById.GetValueOrDefault(dialogActionId);
}
